def url(i,kind):
    if kind=="Google Doc": return f"https://docs.google.com/document/d/{i}/edit"
    if kind=="Google Form": return f"https://docs.google.com/forms/d/{i}/viewform"
    if kind=="Folder": return f"https://drive.google.com/drive/folders/{i}"
    return f"https://drive.google.com/file/d/{i}/view"
